def smallest_distance_pair(nums, k):
    a = sorted(nums); lo, hi = 0, a[-1] - a[0]
    while lo < hi:
        m = (lo + hi) // 2; cnt = 0; j = 0
        for i in range(len(a)):
            while a[i] - a[j] > m: j += 1
            cnt += i - j
        if cnt >= k: hi = m
        else: lo = m + 1
    return lo

