int smallestDistancePair(vector<int>& a, int k) {
    sort(a.begin(), a.end()); int lo = 0, hi = a.back() - a[0];
    while (lo < hi) { int m = (lo + hi) / 2; long long cnt = 0; for (int i = 0, j = 0; i < (int)a.size(); i++) { while (a[i] - a[j] > m) j++; cnt += i - j; } if (cnt >= k) hi = m; else lo = m + 1; }
    return lo;
}
